// PC817 Isolated Input Example
const int ISOLATED_PIN = 2;

void setup() {
  Serial.begin(9600);
  pinMode(ISOLATED_PIN, INPUT_PULLUP); // Active-low via internal pull-up
}

void loop() {
  // When 24V is applied, internal LED lights, phototransistor pulls D2 to LOW
  bool is24VActive = (digitalRead(ISOLATED_PIN) == LOW);

  if (is24VActive) {
    Serial.println("24V Signal DETECTED! Isolated & safe.");
  }
  delay(100);
}
